import os
import requests

def diarized_transcript(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ["ASSEMBLYAI_API_KEY"]
    response = requests.post(
        "https://api.assemblyai.com/v2/transcript",
        headers={
            "authorization": api_key,
            "content-type": "application/json",
        },
        json={
            "audio_url": payload["audio_url"],
            "speaker_labels": True,
            **({"speakers_expected": payload["speakers_expected"]} if "speakers_expected" in payload else {}),
            **({"language_code": payload["language_code"]} if "language_code" in payload else {}),
        },
        timeout=config.get("timeout", 60),
    )
    response.raise_for_status()
    transcript_id = response.json()["id"]

    polling_headers = {"authorization": api_key}
    base_url = f"https://api.assemblyai.com/v2/transcript/{transcript_id}"
    while True:
        poll = requests.get(base_url, headers=polling_headers, timeout=config.get("timeout", 60))
        poll.raise_for_status()
        data = poll.json()
        status = data.get("status")
        if status == "completed":
            break
        if status == "error":
            raise RuntimeError(data.get("error", "AssemblyAI transcription failed"))

    result = {
        "id": data["id"],
        "status": data["status"],
        "text": data.get("text", ""),
        "utterances": data.get("utterances", []),
        "words": data.get("words", []),
        "raw": data,
    }
    return result
